import 'source-map-support/register';
import * as cdk from 'aws-cdk-lib';
import { ContentGenStack } from '../lib/cdk-stack';

const app = new cdk.App();

// The initial admin credential is generated by AWS Secrets Manager inside the
// stack. No credential is read from the environment and none is rendered into
// the synthesized CloudFormation template.
new ContentGenStack(app, process.env.STACK_NAME || 'ContentGenStack', {
  env: {
    account: process.env.CDK_DEFAULT_ACCOUNT || process.env.AWS_ACCOUNT_ID,
    region: process.env.CDK_DEFAULT_REGION || 'us-east-1',
  },
});
